<Variable name="bodyFont" description="Body font" type="font" default="normal normal 16px Inter, system-ui, -apple-system, 'Segoe UI', sans-serif" value="normal normal 16px Inter, system-ui, -apple-system, 'Segoe UI', sans-serif"/>
