/* =====================================================================
   CyberTechMind theme CSS  (clean / flat / content-first)
   TABLE OF CONTENTS
   1. Tokens (dark default + light)   2. Base   3. Header + search
   4. Panels + post grid              5. Home feature strip
   6. Brand panel                     7. Category panels
   8. Article page                    9. Comments / related / pager
   10. Newsletter + footer            11. Ads                12. Responsive
   ===================================================================== */

/* 1. TOKENS ---------------------------------------------------------- */
:root{
  --accent:$(accentColor);
  --bg:$(darkBg);--panel:$(darkPanel);--text:$(darkText);--muted:$(darkMuted);--line:$(darkLine);
  --width:$(contentWidth);--radius:$(cornerRadius);--read:700px;
  --on-accent:#fff;
}
:root[data-theme="light"]{
  --bg:$(lightBg);--panel:$(lightPanel);--text:$(lightText);--muted:$(lightMuted);--line:$(lightLine);
}

/* 2. BASE ------------------------------------------------------------ */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);font:$(bodyFont);line-height:1.6;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{margin:0;line-height:1.25;letter-spacing:-.015em;font-weight:650}
p{margin:0}
ul{margin:0;padding:0;list-style:none}
button{font:inherit;color:inherit}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:4px}
.cm-skip{position:absolute;left:-999px;top:8px;background:var(--accent);color:var(--on-accent);padding:8px 14px;border-radius:8px;z-index:200}
.cm-skip:focus{left:8px}
.cm-wrap{max-width:var(--width);margin:0 auto;padding:0 20px}
.cm-muted{color:var(--muted)}
.cm-wall{position:fixed;inset:0;z-index:-1;background-size:cover;background-position:center;opacity:.18;pointer-events:none}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}}
.section,.widget{margin:0}

/* 3. HEADER + SEARCH ------------------------------------------------- */
.cm-header{position:sticky;top:0;z-index:50;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border-bottom:1px solid transparent;transition:border-color .2s}
.cm-header.is-scrolled{border-color:var(--line)}
.cm-header-in{max-width:var(--width);margin:0 auto;padding:0 20px;height:68px;display:flex;align-items:center;gap:24px}
.cm-logo{font-weight:700;font-size:1.2rem;letter-spacing:-.02em;display:inline-flex;align-items:center;gap:10px}
.cm-logo img{height:32px;width:auto}
.cm-nav{margin-left:auto}
.cm-nav ul{display:flex;gap:4px}
.cm-nav a{display:block;padding:8px 12px;border-radius:8px;color:var(--muted);font-size:.93rem;transition:color .15s,background .15s}
.cm-nav a:hover{color:var(--text);background:color-mix(in srgb,var(--text) 7%,transparent)}
.cm-actions{display:flex;gap:4px}
.cm-nav+.cm-actions{margin-left:0}
.cm-header-in>.cm-actions:first-of-type{margin-left:auto}
.cm-ib{width:38px;height:38px;border:0;border-radius:10px;background:none;color:var(--muted);display:inline-flex;align-items:center;justify-content:center;cursor:pointer;transition:color .15s,background .15s}
.cm-ib:hover{color:var(--text);background:color-mix(in srgb,var(--text) 8%,transparent)}
.cm-burger{display:none}
.cm-ic-sun{display:none}
:root[data-theme="light"] .cm-ic-sun{display:block}
:root[data-theme="light"] .cm-ic-moon{display:none}
.cm-search{position:fixed;inset:0;z-index:100;display:none;align-items:flex-start;justify-content:center;padding:16vh 20px 0;background:color-mix(in srgb,var(--bg) 92%,transparent);backdrop-filter:blur(6px)}
.cm-search.open{display:flex}
.cm-search form{display:flex;gap:8px;width:100%;max-width:620px}
.cm-search input{flex:1;min-width:0;padding:15px 18px;font:inherit;font-size:1.05rem;color:var(--text);background:var(--panel);border:1px solid var(--line);border-radius:12px}
.cm-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:11px 20px;border:0;border-radius:10px;background:var(--accent);color:var(--on-accent);font-weight:600;font-size:.93rem;cursor:pointer;white-space:nowrap;transition:filter .15s}
.cm-btn:hover{filter:brightness(1.1)}
.cm-btn.ghost{background:none;border:1px solid var(--line);color:var(--text)}
.cm-btn.ghost:hover{background:color-mix(in srgb,var(--text) 6%,transparent);filter:none}

/* 4. PANELS + POST GRID ---------------------------------------------- */
.cm-banner{height:220px;margin:8px 0 24px;border-radius:var(--radius);background-size:cover;background-position:center;border:1px solid var(--line)}
.cm-panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;margin-bottom:28px}
.cm-panel-head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:20px 24px 0}
.cm-panel-head h2{font-size:1.15rem}
.cm-panel-head a{color:var(--accent);font-size:.9rem;font-weight:600}
.cm-panel-head a:hover{text-decoration:underline}
.cm-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}
.cm-post{display:flex;flex-direction:column;gap:10px;padding:20px 22px 22px}
.cm-grid>.cm-post{border-left:1px solid var(--line)}
.cm-grid>.cm-post:nth-child(3n+1){border-left:0}
.cm-grid>.cm-post:nth-child(n+4){border-top:1px solid var(--line)}
.cm-img{display:block;aspect-ratio:16/9;border-radius:calc(var(--radius) - 6px);overflow:hidden;background:color-mix(in srgb,var(--text) 6%,transparent)}
.cm-img img{width:100%;height:100%;object-fit:cover;transition:transform .5s}
.cm-post:hover .cm-img img,.cm-mini:hover .cm-img img,.cm-big:hover .cm-img img{transform:scale(1.03)}
.cm-noimg{width:100%;height:100%;background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 30%,var(--panel)),var(--panel))}
.cm-post h3{font-size:1.08rem}
.cm-post h3 a:hover,.cm-mini h3 a:hover,.cm-big h2 a:hover,.cm-rel h3 a:hover{color:var(--accent)}
.cm-ex{color:var(--muted);font-size:.93rem;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.cm-meta{color:var(--muted);font-size:.84rem}
.cm-meta .dot::before{content:"\00b7";margin:0 .5em}
.cm-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:auto;padding-top:4px}
.cm-more{color:var(--accent);font-weight:600;font-size:.88rem;white-space:nowrap}
.cm-more:hover{text-decoration:underline}
.cm-listing-head{padding:8px 0 24px}
.cm-listing-head h1{font-size:1.8rem}
.cm-listing-head p{color:var(--muted);margin-top:6px}
.cm-actions-row{display:flex;justify-content:center;margin:8px 0 36px}
.cm-skel{min-height:260px}
.cm-skel i{display:block;border-radius:8px;background:color-mix(in srgb,var(--text) 7%,transparent);animation:cmpulse 1.2s ease-in-out infinite}
@keyframes cmpulse{50%{opacity:.5}}
.cm-pager{display:flex;justify-content:space-between;gap:12px;margin:0 0 36px}

/* 5. HOME FEATURE STRIP ---------------------------------------------- */
.cm-feature{display:grid;grid-template-columns:1fr 1.9fr 1fr}
.cm-col{display:flex;flex-direction:column}
.cm-col+.cm-big,.cm-big+.cm-col{border-left:1px solid var(--line)}
.cm-mini{display:flex;flex-direction:column;gap:10px;padding:20px 22px;flex:1}
.cm-mini+.cm-mini{border-top:1px solid var(--line)}
.cm-mini h3{font-size:1rem;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.cm-mini .cm-meta{margin-top:auto}
.cm-big{display:flex;flex-direction:column;gap:12px;padding:20px 24px}
.cm-big .cm-img{aspect-ratio:16/8.4}
.cm-big h2{font-size:clamp(1.5rem,2.6vw,2.1rem)}
.cm-big .cm-ex{font-size:1.02rem;-webkit-line-clamp:3}
.cm-big .cm-meta{margin-top:auto}

/* 6. BRAND PANEL ----------------------------------------------------- */
.cm-brand{text-align:center;padding:30px 24px;display:flex;flex-direction:column;align-items:center;gap:6px}
.cm-brand .av{width:64px;height:64px;border-radius:50%;overflow:hidden;background:var(--accent);color:var(--on-accent);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:1.5rem;margin-bottom:6px}
.cm-brand .av img{width:100%;height:100%;object-fit:cover}
.cm-brand strong{font-size:1.05rem}
.cm-brand p{color:var(--muted);font-size:.93rem;max-width:480px;margin-top:8px}
.cm-social{display:flex;gap:6px;margin-top:12px;flex-wrap:wrap;justify-content:center}
.cm-social ul{display:flex;gap:6px}
.cm-social a{width:34px;height:34px;display:inline-flex;align-items:center;justify-content:center;border-radius:8px;color:var(--muted);transition:color .15s,background .15s}
.cm-social a:hover{color:var(--text);background:color-mix(in srgb,var(--text) 8%,transparent)}
.cm-social svg{width:18px;height:18px;fill:currentColor}

/* 7. CATEGORY PANELS (random) ---------------------------------------- */
.cm-cats .cm-panel-head{padding-bottom:4px}
.cm-count{color:var(--muted);font-weight:400;font-size:.88rem;margin-left:8px}

/* 8. ARTICLE PAGE ---------------------------------------------------- */
.cm-article{padding:36px clamp(18px,5vw,56px) 40px}
.cm-crumbs{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;color:var(--muted);font-size:.84rem;margin-bottom:18px}
.cm-crumbs a:hover{color:var(--accent)}
.cm-title{text-align:center;font-size:clamp(1.8rem,4vw,2.7rem);max-width:820px;margin:0 auto 12px}
.cm-sub{text-align:center;color:var(--muted);font-size:1.1rem;max-width:680px;margin:0 auto 14px}
.cm-artmeta{text-align:center;color:var(--muted);font-size:.86rem;margin-bottom:26px}
.cm-hero{border-radius:calc(var(--radius) - 4px);overflow:hidden;margin-bottom:34px;border:1px solid var(--line)}
.cm-hero img{width:100%;aspect-ratio:16/8;object-fit:cover}
.cm-reading{max-width:var(--read);margin:0 auto}
.cm-author{display:flex;align-items:center;gap:12px;margin-bottom:26px}
.cm-author .av{width:38px;height:38px;border-radius:50%;background:var(--accent);color:var(--on-accent);display:flex;align-items:center;justify-content:center;font-weight:700;overflow:hidden}
.cm-author b{display:block;font-size:.93rem}
.cm-author small{color:var(--muted)}
.cm-toc{border:1px solid var(--line);border-radius:12px;padding:14px 18px;margin-bottom:26px;font-size:.93rem}
.cm-toc summary{cursor:pointer;font-weight:600}
.cm-toc ol{margin:10px 0 0;padding-left:20px;color:var(--muted)}
.cm-toc li{margin:4px 0}
.cm-toc li.l3{margin-left:16px}
.cm-toc a:hover{color:var(--accent)}
.cm-body{font-size:1.06rem;line-height:1.78;overflow-wrap:anywhere}
.cm-body>*{margin:0 0 1.25em}
.cm-body h2{font-size:1.55rem;margin-top:1.8em}
.cm-body h3{font-size:1.25rem;margin-top:1.5em}
.cm-body a{color:var(--accent);text-decoration:underline;text-underline-offset:3px}
.cm-body img{border-radius:10px;margin:0 auto}
.cm-body .separator,.cm-body .tr-caption-container{text-align:center}
.cm-body .separator a{margin:0!important}
.cm-body blockquote{margin-left:0;padding:2px 0 2px 18px;border-left:3px solid var(--accent);color:var(--muted)}
.cm-body pre{background:color-mix(in srgb,var(--text) 6%,transparent);border:1px solid var(--line);padding:16px;border-radius:10px;overflow:auto;font-size:.9rem;line-height:1.55}
.cm-body code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.92em}
.cm-body :not(pre)>code{background:color-mix(in srgb,var(--text) 8%,transparent);padding:2px 6px;border-radius:5px}
.cm-body table{display:block;overflow-x:auto;border-collapse:collapse;max-width:100%}
.cm-body td,.cm-body th{border:1px solid var(--line);padding:8px 12px}
.cm-body iframe,.cm-body video{max-width:100%}
.cm-tags{display:flex;flex-wrap:wrap;gap:8px;margin:30px auto 0;max-width:var(--read)}
.cm-tags a{font-size:.82rem;color:var(--muted);border:1px solid var(--line);border-radius:999px;padding:4px 12px;transition:color .15s,border-color .15s}
.cm-tags a:hover{color:var(--accent);border-color:var(--accent)}
.cm-share{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:22px auto 0;max-width:var(--read);color:var(--muted);font-size:.88rem}
.cm-share a,.cm-share button{border:1px solid var(--line);background:none;border-radius:8px;padding:6px 12px;cursor:pointer;color:var(--text);font-size:.85rem}
.cm-share a:hover,.cm-share button:hover{border-color:var(--accent);color:var(--accent)}
.cm-progress{position:fixed;top:0;left:0;height:3px;width:0;background:var(--accent);z-index:120}
.cm-static{padding:36px clamp(18px,5vw,56px) 40px}

/* 9. COMMENTS / RELATED / PAGER -------------------------------------- */
.cm-comments{padding:22px clamp(18px,5vw,40px)}
.cm-comments h4,.cm-comments .comment-form h4{font-size:1rem;margin-bottom:12px}
.cm-comments iframe{width:100%;border:0;background:transparent}
.cm-comments .comments .comment-block{margin:12px 0}
.cm-comments a{color:var(--accent)}
.cm-comments ol,.cm-comments ul{list-style:none;padding:0;margin:0}
.cm-comments .avatar-image-container{display:none}
.cm-comments .comment-content{margin:6px 0}
.cm-related h2{font-size:1.15rem;margin:8px 0 14px}
.cm-rel{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 24px;border-top:1px solid var(--line)}
.cm-rel:first-child{border-top:0}
.cm-rel h3{font-size:1.05rem;margin-bottom:6px}
.cm-rel .cm-ex{margin-bottom:8px}
.cm-rel .cm-img{flex:0 0 240px;aspect-ratio:16/10}

/* 10. NEWSLETTER + FOOTER -------------------------------------------- */
.cm-news{display:grid;grid-template-columns:1.1fr 1fr;gap:24px;align-items:center;padding:28px 30px}
.cm-news h2{font-size:1.25rem;margin-bottom:6px}
.cm-news p{color:var(--muted);font-size:.93rem}
.cm-news form{display:flex;gap:8px}
.cm-news input{flex:1;min-width:0;padding:12px 14px;background:var(--bg);border:1px solid var(--line);border-radius:10px;color:var(--text);font:inherit}
.cm-footer{text-align:center;padding:48px 20px 56px;color:var(--muted);font-size:.9rem}
.cm-footer nav ul{display:flex;gap:6px 22px;justify-content:center;flex-wrap:wrap;margin:14px 0 26px}
.cm-footer a:hover{color:var(--text)}
.cm-footer .mini{display:flex;gap:22px;justify-content:center}

/* 11. ADS ------------------------------------------------------------ */
.cm-ad{margin:0 auto 24px;text-align:center;max-width:100%;overflow:hidden}
.cm-ad .widget{min-height:90px;position:relative;padding-top:18px}
.cm-ad .widget::before{content:"Advertisement";position:absolute;top:0;left:0;right:0;font-size:.68rem;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.cm-ad .section:empty,.cm-ad .section:not(:has(.widget)){display:none}
.cm-ad:not(:has(.widget)){display:none}
body:not(.pt-item) .cm-ad-post{display:none}
body:not(.pt-index) .cm-ad-home{display:none}

/* 12. RESPONSIVE ----------------------------------------------------- */
@media (max-width:900px){
  .cm-feature{grid-template-columns:1fr 1fr}
  .cm-big{grid-column:1/-1;grid-row:1;border-bottom:1px solid var(--line)}
  .cm-col+.cm-big,.cm-big+.cm-col{border-left:0}
  .cm-col+.cm-col{border-left:1px solid var(--line)}
  .cm-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .cm-grid>.cm-post,.cm-grid>.cm-post:nth-child(3n+1),.cm-grid>.cm-post:nth-child(n+4){border:0}
  .cm-grid>.cm-post:nth-child(2n){border-left:1px solid var(--line)}
  .cm-grid>.cm-post:nth-child(n+3){border-top:1px solid var(--line)}
  .cm-news{grid-template-columns:1fr}
}
@media (max-width:720px){
  .cm-burger{display:inline-flex}
  .cm-nav{display:none;position:absolute;top:68px;left:12px;right:12px;margin:0;background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:8px}
  .cm-nav.open{display:block}
  .cm-nav ul{flex-direction:column}
  .cm-feature,.cm-grid{grid-template-columns:1fr}
  .cm-col+.cm-col,.cm-grid>.cm-post:nth-child(2n){border-left:0}
  .cm-grid>.cm-post,.cm-grid>.cm-post:nth-child(n+3){border-top:1px solid var(--line)}
  .cm-grid>.cm-post:first-child{border-top:0}
  .cm-mini+.cm-mini{border-top:1px solid var(--line)}
  .cm-col{border-top:1px solid var(--line)}
  .cm-big{border-bottom:0;order:-1}
  .cm-rel{flex-direction:column-reverse;align-items:stretch}
  .cm-rel .cm-img{flex-basis:auto}
  .cm-news form{flex-direction:column}
  .cm-banner{height:140px}
}

.cm-hide{display:none}
.cm-meta .dot:empty{display:none}
body:not(.pt-index):not(.pt-item) .cm-brand{display:none}
.cm-cats{margin:0}

.cm-nav ul,.cm-footnav ul{display:flex}
.cm-links:empty{display:none}
.cm-footnav ul{gap:6px 22px;justify-content:center;flex-wrap:wrap;margin:14px 0 26px}

/* =====================================================================
   13. POST PAGE (Medium-style: left contents rail / reading column / right ad rail)
   ===================================================================== */
.pt-item #cm-main{max-width:1340px}
.cm-post-layout{display:grid;grid-template-columns:260px minmax(0,700px) 260px;justify-content:center;gap:48px;align-items:start;padding-top:12px}
.cm-rail{min-width:0}
.cm-sticky{position:sticky;top:92px;display:flex;flex-direction:column;gap:22px;max-height:calc(100vh - 110px);overflow:auto;scrollbar-width:thin}
.cm-main-col{min-width:0}
.cm-article{padding:0;margin:0 0 20px;background:none;border:0}
.cm-topics{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px}
.cm-topics a{font-size:.85rem;padding:5px 14px;border:1px solid var(--line);border-radius:999px;color:var(--text);transition:border-color .15s,color .15s}
.cm-topics a:hover{border-color:var(--accent);color:var(--accent)}
.cm-title{text-align:left;font-size:clamp(2rem,4.2vw,3.1rem);font-weight:800;line-height:1.12;letter-spacing:-.025em;max-width:none;margin:0 0 14px}
.cm-sub{text-align:left;color:var(--muted);font-size:1.3rem;line-height:1.45;max-width:none;margin:0 0 26px}
.cm-author{display:flex;align-items:center;gap:14px;margin:0 0 20px}
.cm-author .av,.cm-writer .av{width:46px;height:46px;border-radius:50%;background:var(--accent);color:var(--on-accent);display:flex;align-items:center;justify-content:center;font-weight:700;flex:none}
.cm-author b{font-weight:600}
.cm-author .cm-meta{margin-top:1px}
.cm-share{display:flex;align-items:center;gap:4px;padding:8px 0;margin:0 0 30px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.cm-share a,.cm-share button{width:38px;height:38px;border:0;background:none;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;cursor:pointer;color:var(--muted);padding:0;transition:color .15s,background .15s}
.cm-share a:hover,.cm-share button:hover{color:var(--text);background:color-mix(in srgb,var(--text) 8%,transparent)}
.cm-share button.ok{color:#22c55e}
.cm-share svg{width:19px;height:19px;fill:currentColor}
.cm-share-b{margin:34px 0 26px}
.cm-hero{margin:0 0 34px;border:0;border-radius:6px}
.cm-hero img{aspect-ratio:16/9;width:100%;height:auto;object-fit:cover}
.cm-body{font-family:Charter,'Bitstream Charter','Sitka Text',Cambria,Georgia,'Times New Roman',serif;font-size:1.28rem;line-height:1.78;color:color-mix(in srgb,var(--text) 94%,transparent);letter-spacing:-.003em}
.cm-body>*{margin:0 0 1.45em}
.cm-body h2,.cm-body h3,.cm-body h4{font-family:Inter,system-ui,sans-serif;font-weight:700;letter-spacing:-.02em;line-height:1.25;color:var(--text)}
.cm-body h2{font-size:1.75rem;margin-top:2em}
.cm-body h3{font-size:1.4rem;margin-top:1.7em}
.cm-body img{border-radius:4px}
.cm-tags{margin:34px 0 0;max-width:none}
.cm-writer{display:flex;align-items:center;gap:14px;padding:22px 0 0;margin-top:26px;border-top:1px solid var(--line)}
.cm-writer small{display:block;color:var(--muted);font-size:.8rem}
.cm-writer b{font-size:1.05rem}
.cm-toc{font-size:.92rem}
.cm-toc[hidden],.cm-about[hidden]{display:none}
.cm-toc h2{font-size:.78rem;text-transform:uppercase;letter-spacing:.09em;color:var(--muted);margin:0 0 12px;font-weight:600}
.cm-toc ol{list-style:none;margin:0;padding:0;border-left:1px solid var(--line)}
.cm-toc li{margin:0}
.cm-toc li.l3 a{padding-left:28px;font-size:.88rem}
.cm-toc a{display:block;padding:6px 12px 6px 16px;margin-left:-1px;border-left:2px solid transparent;color:var(--muted);line-height:1.4;transition:color .15s,border-color .15s}
.cm-toc a:hover{color:var(--text)}
.cm-toc a.on{color:var(--accent);border-left-color:var(--accent);font-weight:600}
.cm-about{font-size:.92rem;color:var(--muted)}
.cm-about b{display:block;color:var(--text);font-size:1.02rem;margin-bottom:6px}
.cm-about p{margin:0 0 10px}
.cm-comments{padding:26px 0 0;margin-top:10px;border-top:1px solid var(--line)}
.cm-comments h4{font-size:1.2rem;margin-bottom:14px}
.cm-related{margin-top:34px;padding-top:26px;border-top:1px solid var(--line)}
.cm-related .cm-panel{margin:0}
.cm-ad-sl,.cm-ad-sr{margin:0}
.cm-ad-sl .widget,.cm-ad-sr .widget{min-height:250px}
@media (max-width:1240px){
  .cm-post-layout{grid-template-columns:minmax(0,700px);gap:0}
  .cm-rail-l{order:-1}
  .cm-rail-r{order:2}
  .cm-sticky{position:static;max-height:none;overflow:visible}
  .cm-rail-l .cm-sticky{margin-bottom:22px}
  .cm-toc{border:1px solid var(--line);border-radius:12px;padding:14px 16px}
  .cm-toc ol{border-left:0}
  .cm-rail-r .cm-sticky{margin-top:30px}
  .cm-rail-l .cm-ad,.cm-rail-r .cm-ad{margin-top:8px}
}
@media (max-width:720px){
  .cm-body{font-size:1.14rem}
  .cm-sub{font-size:1.12rem}
}

.pt-item .cm-header-in{max-width:1340px}
.cm-hero.small{text-align:center}
.cm-hero.small img{width:auto;max-width:100%;aspect-ratio:auto;margin:0 auto}

/* =====================================================================
   14. LAYOUT AREAS + GADGET STYLING
   ===================================================================== */
/* header logo gadget / main menu gadget replace the variable-driven ones when present */
.cm-logo-sec .widget{margin:0}
.cm-logo-sec .widget h2,.cm-logo-sec .widget .title{display:none}
.cm-logo-sec img{height:34px;width:auto;max-width:200px}
.cm-header:has(.cm-logo-sec .widget) .cm-logo{display:none}
.cm-nav .widget{margin:0}
.cm-nav .widget>h2,.cm-nav .widget>h3{display:none}
.cm-nav .widget ul{display:flex;gap:4px;list-style:none;margin:0;padding:0}
.cm-nav .widget li{margin:0;padding:0}
.cm-nav .widget a{display:block;padding:8px 12px;border-radius:8px;color:var(--muted);font-size:.93rem}
.cm-nav .widget a:hover{color:var(--text);background:color-mix(in srgb,var(--text) 7%,transparent)}
.cm-nav:has(.widget) .cm-links{display:none}
@media (max-width:720px){.cm-nav .widget ul{flex-direction:column}}

/* home-only areas */
.cm-home-only{display:none}
body.is-home .cm-home-only{display:block}
.cm-hero-sec:not(:has(.widget)),.cm-feat-sec:not(:has(.widget)){display:none}
.cm-hero-sec{margin:6px 0 28px;text-align:center}
.cm-hero-sec .widget{margin:0 0 14px}
.cm-hero-sec .widget>h2,.cm-hero-sec .widget>.title{font-size:clamp(1.8rem,4vw,2.8rem);font-weight:800;letter-spacing:-.025em;margin:0 0 10px}
.cm-hero-sec .widget-content{color:var(--muted);font-size:1.08rem;max-width:720px;margin:0 auto}
.cm-hero-sec img{border-radius:var(--radius);margin:0 auto}
.cm-hero-sec form{display:flex;gap:8px;max-width:560px;margin:8px auto 0}
.cm-hero-sec input[type=text],.cm-hero-sec input[type=search]{flex:1;min-width:0;padding:13px 16px;background:var(--panel);border:1px solid var(--line);border-radius:12px;color:var(--text);font:inherit}
.cm-hero-sec input[type=submit],.cm-hero-sec button{padding:0 22px;border:0;border-radius:12px;background:var(--accent);color:var(--on-accent);font-weight:600;cursor:pointer}
.cm-feat-sec{margin:0 0 28px}
.cm-feat-sec .widget{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:22px 24px}
.cm-feat-sec .widget>h2,.cm-feat-sec .widget>.title{font-size:.8rem;text-transform:uppercase;letter-spacing:.09em;color:var(--muted);margin:0 0 14px;font-weight:600}
.cm-feat-sec .post-summary h3,.cm-feat-sec .post-summary h3 a{font-size:1.4rem;font-weight:700;color:var(--text)}
.cm-feat-sec .post-summary a:hover{color:var(--accent)}
.cm-feat-sec img{border-radius:10px;width:100%;height:auto;margin-bottom:12px}

/* sidebar + sidebar-like areas */
.cm-sidebar:not(:has(.widget)){display:none}
.cm-split{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:32px;align-items:start}
.cm-split .cm-sidebar{position:sticky;top:92px}
.cm-rail-r .cm-sidebar{display:block}
@media (max-width:1000px){.cm-split{grid-template-columns:1fr}.cm-split .cm-sidebar{position:static}}
.cm-sidebar .widget,.cm-foot-col .widget,.cm-pfe .widget{margin:0 0 22px}
.cm-sidebar .widget{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:18px 20px}
.widget>h2,.widget>h3.title{font-size:.8rem;text-transform:uppercase;letter-spacing:.09em;color:var(--muted);margin:0 0 12px;font-weight:600}
.cm-sidebar .widget ul,.cm-foot-col .widget ul{list-style:none;margin:0;padding:0}
.cm-sidebar .widget li,.cm-foot-col .widget li{margin:0;padding:6px 0;border-top:1px solid var(--line)}
.cm-sidebar .widget li:first-child,.cm-foot-col .widget li:first-child{border-top:0}
.cm-sidebar .widget a:hover,.cm-foot-col .widget a:hover{color:var(--accent)}
.widget .widget-content{color:var(--muted);font-size:.93rem;line-height:1.6}
.widget img{max-width:100%;height:auto}
/* labels: list + cloud as chips */
.Label .label-size,.Label .cloud-label-widget-content span{display:inline-block;margin:0 6px 6px 0}
.Label .cloud-label-widget-content a,.Label .label-size a{display:inline-block;padding:4px 12px;border:1px solid var(--line);border-radius:999px;font-size:.84rem;color:var(--text)}
.Label .label-count{color:var(--muted);margin-left:4px}
/* popular posts / related lists */
.PopularPosts .widget-content ul li{display:flex;gap:12px;align-items:flex-start}
.PopularPosts .item-thumbnail{flex:0 0 64px;float:none;margin:0}
.PopularPosts .item-thumbnail img{width:64px;height:64px;object-fit:cover;border-radius:8px}
.PopularPosts .item-title{font-weight:600;color:var(--text);line-height:1.35}
.PopularPosts .item-snippet{display:none}
/* search box, follow by email, contact form, followers */
.BlogSearch input[type=text],.BlogSearch .gsc-input,.FollowByEmail input[type=text],.FollowByEmail input[type=email],.ContactForm input,.ContactForm textarea{width:100%;padding:11px 14px;background:var(--bg);border:1px solid var(--line);border-radius:10px;color:var(--text);font:inherit;margin:0 0 8px}
.BlogSearch input[type=submit],.FollowByEmail input[type=submit],.ContactForm .contact-form-button{padding:11px 20px;border:0;border-radius:10px;background:var(--accent);color:var(--on-accent);font-weight:600;cursor:pointer;width:auto}
.ContactForm .contact-form-error-message,.ContactForm .contact-form-success-message{font-size:.85rem}
.FollowByEmail .follow-by-email-inner td{display:block;padding:0}
.FollowByEmail .follow-by-email-inner table{width:100%}
.cm-pfe:not(:has(.widget)){display:none}
.cm-pfe{margin-top:30px}
.cm-pfe .widget{background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);padding:22px 24px}
.HTML .widget-content{color:var(--text)}
.Text .widget-content,.Image .widget-content{color:var(--muted)}

/* footer */
.cm-footer{text-align:left;padding:0 0 40px;color:var(--muted);font-size:.9rem}
.cm-foot-cols{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:34px;max-width:var(--width);margin:0 auto;padding:44px 20px 10px;border-top:1px solid var(--line)}
.cm-foot-cols:not(:has(.widget)){display:none}
.cm-foot-bottom{display:flex;flex-direction:column;align-items:center;gap:6px;padding:30px 20px 0;text-align:center}
.cm-foot-cols:not(:has(.widget))+.cm-foot-bottom{padding-top:48px}
.cm-copy .widget{margin:0}
.cm-copy .widget>h2{display:none}
.cm-copy:has(.widget) .cm-copy-default{display:none}
.cm-footnav .widget{margin:0}
.cm-footnav .widget>h2{display:none}
.cm-footnav .widget ul{display:flex;gap:6px 22px;justify-content:center;flex-wrap:wrap;list-style:none;margin:14px 0 26px;padding:0}
.cm-footnav:has(.widget) .cm-links{display:none}
.cm-footnav .widget li{margin:0;padding:0;border:0}
@media (max-width:820px){.cm-foot-cols{grid-template-columns:1fr}}

/* =====================================================================
   15. THREE-COLUMN SHELL (left rail / content / right rail) + POLISH
   ===================================================================== */
#cm-main,.pt-item #cm-main{max-width:var(--width)}
.cm-header-in,.pt-item .cm-header-in{max-width:var(--width)}
.cm-shell{display:grid;grid-template-columns:230px minmax(0,1fr) 300px;gap:36px;align-items:start;padding-top:12px}
.cm-content{min-width:0}
.cm-box{margin:0 0 26px}
.cm-box h2,.cm-catnav h2{font-size:.74rem;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);margin:0 0 10px;font-weight:600}
.cm-row{display:flex;gap:12px;align-items:flex-start;padding:11px 0;border-top:1px solid var(--line)}
.cm-box h2+.cm-row,.cm-hlist .cm-row:first-child{border-top:0}
.cm-row-img{flex:0 0 60px;height:60px;border-radius:10px;overflow:hidden;background:color-mix(in srgb,var(--text) 7%,transparent)}
.cm-row-img img{width:100%;height:100%;object-fit:cover}
.cm-row-tx{display:flex;flex-direction:column;gap:3px;min-width:0}
.cm-row-t{font-weight:600;font-size:.92rem;line-height:1.35;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;transition:color .15s}
.cm-row:hover .cm-row-t{color:var(--accent)}
.cm-catnav ul{list-style:none;margin:0;padding:0}
.cm-catnav a{display:block;padding:7px 12px;border-radius:8px;color:var(--muted);font-size:.93rem;transition:background .15s,color .15s}
.cm-catnav a:hover{background:color-mix(in srgb,var(--text) 7%,transparent);color:var(--text)}
.cm-catnav a.on{background:color-mix(in srgb,var(--accent) 14%,transparent);color:var(--accent);font-weight:600}
.cm-about{font-size:.9rem;color:var(--muted);margin-top:22px;padding:14px 16px;border:1px solid var(--line);border-radius:12px}
.cm-about b{display:block;color:var(--text);margin-bottom:4px}
.cm-about p{margin:0}
.cm-sticky{gap:6px}
/* home feature: big post + compact list */
.cm-feature{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr)}
.cm-feature .cm-big{border:0}
.cm-hlist{border-left:1px solid var(--line);padding:10px 20px;display:flex;flex-direction:column;justify-content:center}
.cm-big .cm-foot{margin-top:auto}
/* post page */
.cm-article{margin:0 0 6px}
.cm-byline{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:0 0 28px}
.cm-byline .cm-author{margin:0}
.cm-share{border:0;margin:0;padding:0;gap:6px}
.cm-share-l{font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);margin-right:6px}
.cm-share a,.cm-share button{border:1px solid var(--line);width:36px;height:36px}
.cm-hero{border-radius:16px;margin:0 0 32px}
.cm-body{font-family:inherit;font-size:1.06rem;line-height:1.82;letter-spacing:0}
.cm-body>*{margin:0 0 1.35em}
.cm-body h2{font-size:1.6rem}
.cm-body h3{font-size:1.3rem}
.cm-comments{margin-top:40px;padding:34px 0 0;border-top:1px solid var(--line)}
.cm-ch{display:flex;align-items:center;gap:10px;font-size:1.35rem;margin:0 0 18px}
.cm-ch svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:2;stroke-linejoin:round}
.cm-cbox{border:1px solid var(--line);border-radius:16px;padding:14px;margin:0 0 24px}
.cm-cinput{display:block;min-height:76px;padding:10px 12px;color:var(--muted);border:1px solid var(--line);border-radius:10px;font-size:.95rem}
.cm-cinput:hover{border-color:var(--accent)}
.cm-cbtn{display:flex;justify-content:flex-end;margin-top:12px}
.cm-comment{display:flex;gap:14px;border:1px solid var(--line);border-radius:16px;padding:18px;margin:0 0 14px}
.cm-comment .av{width:36px;height:36px;flex:none;border-radius:50%;display:flex;align-items:center;justify-content:center;background:color-mix(in srgb,var(--text) 8%,transparent);color:var(--muted);font-weight:600}
.cm-ctop{display:flex;flex-direction:column;margin-bottom:6px}
.cm-comment p{margin:0;line-height:1.6}
/* header CTA */
.cm-cta{padding:9px 18px;font-size:.88rem}
/* professional footer */
.cm-footer{margin-top:56px;padding:0;text-align:left;border-top:1px solid var(--line);background:color-mix(in srgb,var(--panel) 55%,var(--bg))}
.cm-foot-in{max-width:var(--width);margin:0 auto;padding:0 20px}
.cm-foot-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:44px;padding:54px 0 38px}
.cm-footname{display:block;font-size:1.3rem;font-weight:800;letter-spacing:-.02em;color:var(--text);margin-bottom:10px}
.cm-footbrand p{color:var(--muted);max-width:340px;margin:0 0 16px;line-height:1.6}
.cm-footbrand .cm-social{margin:0 0 22px;justify-content:flex-start}
.cm-sublabel{display:block;font-weight:600;color:var(--text);margin-bottom:8px;font-size:.93rem}
.cm-subrow{display:flex;gap:8px;max-width:380px}
.cm-subrow input{flex:1;min-width:0;padding:11px 14px;background:var(--bg);border:1px solid var(--line);border-radius:10px;color:var(--text);font:inherit}
.cm-foot-col .widget{margin:0}
.cm-foot-col .widget ul{list-style:none;margin:0;padding:0}
.cm-foot-col .widget li{padding:5px 0;border:0;margin:0}
.cm-foot-col .widget a{color:var(--muted);font-size:.93rem}
.cm-foot-col .widget a:hover{color:var(--text)}
.cm-foot-col .label-count{margin-left:6px;font-size:.8rem;opacity:.7}
.cm-foot-bottom{display:flex;flex-direction:row;flex-wrap:wrap;gap:12px 28px;align-items:center;justify-content:space-between;padding:20px 0 30px;border-top:1px solid var(--line);text-align:left}
.cm-foot-bottom .mini{display:flex;gap:18px;align-items:center}
.cm-totop{background:none;border:1px solid var(--line);border-radius:999px;padding:6px 14px;color:var(--muted);cursor:pointer;font-size:.85rem}
.cm-totop:hover{color:var(--text);border-color:var(--muted)}
.cm-footnav .widget ul{margin:0}
.cm-footnav .widget ul,.cm-footnav .cm-links{margin:0}
@media (max-width:1240px){
  .cm-shell{grid-template-columns:minmax(0,1fr);gap:0}
  .cm-content{order:-1}
  .cm-rail-l{order:-2}
  .cm-rail-l:not(:has(.cm-toc:not([hidden]))){display:none}
  .cm-rail-l .cm-catnav,.cm-rail-l .cm-about{display:none}
  .cm-rail-r{margin-top:30px}
  .cm-feature{grid-template-columns:1fr}
  .cm-hlist{border-left:0;border-top:1px solid var(--line)}
}
@media (max-width:900px){.cm-foot-top{grid-template-columns:1fr 1fr}}
@media (max-width:720px){.cm-cta{display:none}.cm-foot-top{grid-template-columns:1fr;gap:30px}.cm-foot-bottom{flex-direction:column;align-items:flex-start}}

/* sticky needs the rail to span the full row height */
.cm-shell{align-items:stretch}
.cm-shell>.cm-rail{align-self:stretch}
.cm-shell>.cm-content{align-self:start}
.cm-comments .cm-btn,.cm-comments a.cm-btn{color:var(--on-accent)}
.cm-comments a.cm-cinput{color:var(--muted)}

/* =====================================================================
   16. COLLAPSIBLE SIDEBAR + SKELETON LOADERS
   ===================================================================== */
:root{--sbw:260px}
:root[data-sb="min"]{--sbw:76px}
.cm-shell{grid-template-columns:var(--sbw) minmax(0,1fr) 300px;transition:grid-template-columns .25s ease}
.cm-i{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;flex:none}
.cm-sb{position:sticky;top:84px;display:flex;flex-direction:column;background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:12px;max-height:calc(100vh - 100px);overflow:hidden auto;scrollbar-width:thin}
.cm-sb-head{display:flex;align-items:center;gap:12px;padding:8px;border-radius:12px;color:var(--text);transition:background .15s}
.cm-sb-head:hover,.cm-sb-foot:hover{background:color-mix(in srgb,var(--text) 6%,transparent)}
.cm-sb-tile{flex:none;width:40px;height:40px;border-radius:12px;background:var(--accent);color:var(--on-accent);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:1.1rem;overflow:hidden}
.cm-sb-tile img{width:100%;height:100%;object-fit:cover}
.cm-sb-htx{display:flex;flex-direction:column;min-width:0;flex:1;line-height:1.25}
.cm-sb-htx b{font-size:.95rem;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cm-sb-htx small{color:var(--muted);font-size:.8rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cm-sb-ud{margin-left:auto;color:var(--muted)}
.cm-sb-glabel{font-size:.78rem;color:var(--muted);padding:16px 10px 6px}
.cm-sb-menu{list-style:none;margin:0;padding:0}
.cm-sb-item{display:flex;align-items:center;gap:12px;width:100%;padding:9px 10px;border:0;background:none;border-radius:10px;color:var(--text);font:inherit;font-size:.93rem;cursor:pointer;text-align:left;transition:background .15s,color .15s}
.cm-sb-item:hover{background:color-mix(in srgb,var(--text) 7%,transparent)}
.cm-sb-item.active{background:color-mix(in srgb,var(--accent) 14%,transparent);color:var(--accent);font-weight:600}
.cm-sb-label{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cm-sb-chev{margin-left:auto;color:var(--muted);transition:transform .2s}
.cm-sb-li.has-sub.open>.cm-sb-item .cm-sb-chev{transform:rotate(90deg)}
.cm-sb-li[hidden]{display:none}
.cm-sb-sub{list-style:none;margin:2px 0 8px 19px;padding:0 0 0 10px;border-left:1px solid var(--line);display:none}
.cm-sb-li.open>.cm-sb-sub{display:block}
.cm-sb-sub li{margin:0}
.cm-sb-sub a{display:block;padding:7px 10px;border-radius:8px;color:var(--muted);font-size:.9rem;line-height:1.4;transition:background .15s,color .15s}
.cm-sb-sub a:hover{background:color-mix(in srgb,var(--text) 7%,transparent);color:var(--text)}
.cm-sb-sub a.on{color:var(--accent);background:color-mix(in srgb,var(--accent) 12%,transparent);font-weight:600}
.cm-sb-sub li.l3 a{padding-left:22px;font-size:.86rem}
.cm-sb-sub .cm-sk{margin:10px 8px}
.cm-sb-foot{display:flex;align-items:center;gap:12px;padding:12px 8px 8px;margin-top:14px;border-top:1px solid var(--line);color:var(--text);border-radius:12px;transition:background .15s}
.cm-sb-av{flex:none;width:38px;height:38px;border-radius:50%;background:color-mix(in srgb,var(--accent) 16%,transparent);color:var(--accent);display:flex;align-items:center;justify-content:center}
.cm-sb .cm-ad{margin:14px 0 0}
/* collapsed icon rail (desktop) */
@media (min-width:1241px){
  :root[data-sb="min"] .cm-sb{padding:12px 8px;align-items:center}
  :root[data-sb="min"] .cm-sb-htx,:root[data-sb="min"] .cm-sb-ud,:root[data-sb="min"] .cm-sb-label,:root[data-sb="min"] .cm-sb-chev,:root[data-sb="min"] .cm-sb-glabel,:root[data-sb="min"] .cm-sb-sub{display:none!important}
  :root[data-sb="min"] .cm-sb-head,:root[data-sb="min"] .cm-sb-foot{justify-content:center;padding:6px;gap:0}
  :root[data-sb="min"] .cm-sb-menu{margin-top:16px;width:100%}
  :root[data-sb="min"] .cm-sb-item{justify-content:center;padding:11px 0}
  :root[data-sb="min"] .cm-sb .cm-ad{display:none}
}
/* mobile / tablet: off-canvas drawer */
@media (max-width:1240px){
  .cm-rail-l,.cm-rail-l:not(:has(.cm-toc:not([hidden]))){display:block!important;position:fixed;top:68px;left:0;bottom:0;width:min(310px,88vw);z-index:70;transform:translateX(-105%);transition:transform .25s ease;padding:10px;order:0}
  .sb-open .cm-rail-l{transform:none}
  .cm-sb{position:static;max-height:none;height:100%;box-shadow:0 20px 50px rgba(0,0,0,.35)}
  body.sb-open::after{content:"";position:fixed;inset:68px 0 0 0;background:rgba(0,0,0,.5);z-index:65}
}
.cm-sbtoggle{margin-right:-8px}
/* skeleton loaders */
.cm-sk{display:block;border-radius:8px;background:linear-gradient(90deg,color-mix(in srgb,var(--text) 7%,transparent) 25%,color-mix(in srgb,var(--text) 14%,transparent) 37%,color-mix(in srgb,var(--text) 7%,transparent) 63%);background-size:400% 100%;animation:cmshine 1.4s ease infinite}
@keyframes cmshine{0%{background-position:100% 50%}100%{background-position:0 50%}}
.cm-row .cm-sk:first-child{flex:none;border-radius:10px}
.cm-row-tx .cm-sk{margin:4px 0}
.cm-loading .cm-post{pointer-events:none}
.cm-post>.cm-sk{margin:0}

/* =====================================================================
   17. TWO-ROW NAVBAR + MEGA MENU
   ===================================================================== */
:root{--hh:118px}
.cm-header{background:color-mix(in srgb,var(--bg) 90%,transparent)}
.cm-header-in{height:68px}
.cm-actions{margin-left:auto}
.cm-subnav{position:relative;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.cm-header.is-scrolled .cm-subnav{border-bottom-color:var(--line)}
.cm-subnav.empty .cm-mega-nav{display:none}
.cm-subnav-in{max-width:var(--width);margin:0 auto;padding:0 20px;height:48px;display:flex;align-items:center;justify-content:space-between;gap:20px}
.cm-mega-nav{display:flex;align-items:center;gap:2px;min-width:0;overflow:visible}
.cm-mi{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border:0;border-radius:9px;background:none;color:var(--muted);font:inherit;font-size:.9rem;font-weight:600;cursor:pointer;white-space:nowrap;transition:color .15s,background .15s}
.cm-mi:hover,.cm-mi.open{color:var(--text);background:color-mix(in srgb,var(--text) 7%,transparent)}
.cm-mi.current{color:var(--text)}
.cm-mi .cm-mi-chev{width:14px;height:14px;transform:rotate(90deg);transition:transform .2s}
.cm-mi.open .cm-mi-chev{transform:rotate(-90deg)}
.cm-subnav .cm-nav{margin:0;display:block}
.cm-subnav .cm-nav ul{display:flex;gap:2px}
.cm-subnav .cm-nav a{padding:8px 12px;font-size:.88rem}
/* panel */
.cm-mega-wrap{position:absolute;top:100%;left:0;right:0;pointer-events:none;z-index:5}
.cm-mega{pointer-events:auto;max-width:var(--width);margin:8px auto 0;width:calc(100% - 40px);background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:0 30px 60px rgba(0,0,0,.35);overflow:hidden;opacity:0;transform:translateY(-6px);transition:opacity .18s ease,transform .18s ease}
.cm-mega.open{opacity:1;transform:none}
.cm-mega[hidden]{display:none}
.cm-mega-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,.85fr) 340px;gap:36px;padding:28px 30px}
.cm-mcol h3{font-size:.74rem;text-transform:uppercase;letter-spacing:.1em;color:var(--text);margin:0 0 14px;font-weight:700}
.cm-mlink{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:7px 0;color:var(--muted);font-size:.93rem;line-height:1.4;transition:color .15s,transform .15s}
.cm-mlink span{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.cm-mlink small{flex:none;font-size:.78rem;opacity:.75}
.cm-mlink:hover{color:var(--accent);transform:translateX(3px)}
.cm-mall{color:var(--accent);font-weight:600;margin-top:6px}
.cm-mlist.two{display:grid;grid-template-columns:1fr 1fr;column-gap:16px}
.cm-promo{position:relative;display:flex;flex-direction:column;justify-content:flex-end;gap:8px;min-height:250px;padding:20px;border-radius:14px;overflow:hidden;color:#fff;background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 70%,#000),#10111a) center/cover;isolation:isolate}
.cm-promo::before{content:"";position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,.82),rgba(0,0,0,.08) 70%);z-index:-1}
.cm-promo-k{font-size:.72rem;letter-spacing:.1em;text-transform:uppercase;opacity:.85;font-weight:600}
.cm-promo strong{font-size:1.15rem;line-height:1.25;font-weight:700;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.cm-btn.light{background:#fff;color:#111;align-self:flex-start;padding:9px 16px;font-size:.85rem}
.cm-promo:hover .cm-btn.light{filter:brightness(.94)}
.cm-mega .cm-sk{display:block}
/* sticky offsets follow the taller header on desktop */
.cm-sb{top:calc(var(--hh) + 12px);max-height:calc(100vh - var(--hh) - 28px)}
.cm-sticky{top:calc(var(--hh) + 12px);max-height:calc(100vh - var(--hh) - 28px)}
html{scroll-padding-top:calc(var(--hh) + 16px)}
@media (max-width:1240px){
  :root{--hh:68px}
  .cm-subnav{display:none}
  .cm-actions{margin-left:auto}
}

/* =====================================================================
   18. MOBILE / TABLET (must come last so it wins over the desktop shell rules)
   ===================================================================== */
@media (max-width:1240px){
  .cm-shell{grid-template-columns:minmax(0,1fr);gap:0}
  .cm-content{order:0}
  .cm-rail-r{order:1;margin-top:28px}
  .cm-rail-r .cm-sticky{position:static;max-height:none;overflow:visible}
  .cm-box{margin-bottom:20px}
  .cm-wrap,.cm-header-in,.cm-subnav-in{padding-left:16px;padding-right:16px}
}
@media (max-width:720px){
  .cm-header-in{height:60px;gap:10px}
  :root{--hh:60px}
  .cm-rail-l,.cm-rail-l:not(:has(.cm-toc:not([hidden]))){top:60px}
  body.sb-open::after{inset:60px 0 0 0}
  .cm-logo{font-size:1.05rem;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .cm-logo img{height:28px}
  .cm-ib{width:40px;height:40px}
  .cm-panel{border-radius:14px;margin-bottom:20px}
  .cm-panel-head{padding:16px 16px 0;flex-wrap:wrap}
  .cm-grid{grid-template-columns:1fr}
  .cm-grid>.cm-post,.cm-grid>.cm-post:nth-child(n){border-left:0}
  .cm-grid>.cm-post:nth-child(n+2){border-top:1px solid var(--line)}
  .cm-post{padding:16px}
  .cm-big{padding:16px}
  .cm-big h2{font-size:1.45rem}
  .cm-hlist{padding:6px 16px}
  .cm-feature{grid-template-columns:1fr}
  .cm-title{font-size:1.9rem;line-height:1.15}
  .cm-sub{font-size:1.05rem}
  .cm-byline{align-items:flex-start;flex-direction:column;gap:14px}
  .cm-hero{border-radius:12px;margin-bottom:24px}
  .cm-body{font-size:1.02rem;line-height:1.75}
  .cm-body h2{font-size:1.4rem}
  .cm-body h3{font-size:1.2rem}
  .cm-body table,.cm-body pre{max-width:100%;overflow-x:auto}
  .cm-comment{padding:14px;gap:10px}
  .cm-cbox{padding:10px}
  .cm-listing-head h1{font-size:1.5rem}
  .cm-actions-row .cm-btn{width:100%}
  .cm-pager{flex-direction:column}
  .cm-pager .cm-btn{width:100%}
  .cm-footer{margin-top:36px}
  .cm-foot-top{padding:36px 0 24px}
  .cm-foot-bottom{padding:18px 0 26px;gap:14px}
  .cm-foot-bottom .mini{flex-wrap:wrap;gap:12px 16px}
  .cm-subrow{max-width:none}
  .cm-search{padding-top:12vh}
  .cm-search form{flex-direction:column}
  .cm-search .cm-btn{padding:13px}
  .cm-hero-sec .widget>h2,.cm-hero-sec .widget>.title{font-size:1.7rem}
  .cm-hero-sec form{flex-direction:column}
  .cm-hero-sec input[type=submit],.cm-hero-sec button{padding:12px}
}
@media (max-width:420px){
  .cm-cta{display:none}
  .cm-share{flex-wrap:wrap}
  .cm-share-l{width:100%;margin:0 0 4px}
}
/* tap targets + safe areas */
@media (hover:none){
  .cm-sb-item,.cm-sb-sub a,.cm-mlink{min-height:44px;display:flex;align-items:center}
  .cm-sb-sub a{display:flex}
}
body{padding-bottom:env(safe-area-inset-bottom)}
img,video,iframe,table{max-width:100%}
.cm-body img,.cm-body iframe,.cm-body video{height:auto}
@media (max-width:1240px){
  body.sb-open .cm-rail-l,body.sb-open .cm-rail-l:not(:has(.cm-toc:not([hidden]))){transform:none!important}
  .cm-rail-l,.cm-rail-l:not(:has(.cm-toc:not([hidden]))){visibility:hidden;transition:transform .25s ease,visibility 0s linear .25s}
  body.sb-open .cm-rail-l,body.sb-open .cm-rail-l:not(:has(.cm-toc:not([hidden]))){visibility:visible;transition:transform .25s ease}
  .cm-rail-l .cm-catnav,.cm-rail-l .cm-about{display:block}
}

/* =====================================================================
   19. POST BLOCKS (code windows, mermaid, callouts, figures, slider, tables)
   ===================================================================== */
:root{
  --code-bg:#1b1d22;--code-bar:#25272d;--code-fg:#d7dae0;--code-line:#32353c;--code-muted:#7d8590;
  --t-kw:#ff7b72;--t-str:#a5d6ff;--t-num:#79c0ff;--t-fn:#d2a8ff;--t-attr:#7ee787;--t-type:#ffa657;--t-com:#7d8590;
}
:root[data-theme="light"]{
  --code-bg:#fbfbfd;--code-bar:#eceef2;--code-fg:#24292f;--code-line:#dfe2e8;--code-muted:#6e7781;
  --t-kw:#cf222e;--t-str:#0a3069;--t-num:#0550ae;--t-fn:#8250df;--t-attr:#116329;--t-type:#953800;--t-com:#6e7781;
}
/* ---- macOS window ---- */
.cm-win{margin:0 0 1.5em;border:1px solid var(--code-line);border-radius:12px;background:var(--code-bg);overflow:hidden;box-shadow:0 10px 30px rgba(0,0,0,.18);font-family:Inter,system-ui,sans-serif}
.cm-win-bar{display:flex;align-items:center;gap:12px;padding:10px 12px;background:var(--code-bar);border-bottom:1px solid var(--code-line);cursor:pointer;user-select:none}
.cm-win[data-state="closed"] .cm-win-bar{border-bottom-color:transparent}
.cm-dots{display:flex;gap:8px;flex:none}
.cm-dots .d{position:relative;width:13px;height:13px;padding:0;border:0;border-radius:50%;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;font:700 9px/1 Inter,sans-serif;color:rgba(0,0,0,.55)}
.cm-dots .r{background:#ff5f57}.cm-dots .y{background:#febc2e}.cm-dots .g{background:#28c840}
.cm-dots:hover .r::before{content:"\00d7";font-size:12px}
.cm-dots:hover .y::before{content:"\2013"}
.cm-dots:hover .g::before{content:"+";font-size:11px}
.cm-win-title{display:inline-flex;align-items:center;gap:8px;min-width:0;border:0;background:none;color:var(--code-muted);font:inherit;font-size:.82rem;font-weight:600;cursor:pointer;padding:0}
.cm-win-title .cm-i{width:15px;height:15px}
.cm-win-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--code-fg);opacity:.85}
.cm-win-tabs{display:flex;gap:4px;min-width:0;overflow-x:auto;scrollbar-width:none}
.cm-tab{border:0;background:none;color:var(--code-muted);font:inherit;font-size:.8rem;font-weight:600;padding:5px 11px;border-radius:7px;cursor:pointer;white-space:nowrap}
.cm-tab:hover{color:var(--code-fg)}
.cm-tab.on{background:var(--code-bg);color:var(--code-fg);box-shadow:inset 0 0 0 1px var(--code-line)}
.cm-win-right{margin-left:auto;display:flex;align-items:center;gap:10px;flex:none}
.cm-win-meta{display:flex;gap:10px;font-size:.74rem;color:var(--code-muted);font-weight:600}
.cm-win-lang{text-transform:uppercase;letter-spacing:.06em}
.cm-win-copy{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--code-line);background:var(--code-bg);color:var(--code-muted);font:inherit;font-size:.75rem;font-weight:600;padding:4px 10px;border-radius:7px;cursor:pointer;transition:color .15s,border-color .15s}
.cm-win-copy:hover{color:var(--code-fg);border-color:var(--code-muted)}
.cm-win-copy.ok{color:#28c840;border-color:#28c840}
.cm-win-copy .cm-i{width:14px;height:14px}
.cm-win-chev{width:16px;height:16px;color:var(--code-muted);transition:transform .2s}
.cm-win:not([data-state="closed"]) .cm-win-chev{transform:rotate(90deg)}
.cm-win-wrap{display:grid;grid-template-rows:0fr;transition:grid-template-rows .28s ease}
.cm-win:not([data-state="closed"]) .cm-win-wrap{grid-template-rows:1fr}
.cm-win-inner{min-height:0;overflow:hidden}
.cm-win-view{display:flex;overflow:auto;max-height:none}
.cm-win[data-state="preview"] .cm-win-view{max-height:15.5em}
.cm-win[data-state="preview"][data-long] .cm-win-more{display:flex}
.cm-gutter{flex:none;padding:16px 0 16px 14px;text-align:right;white-space:pre;color:var(--code-muted);opacity:.6;font:13px/1.65 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;user-select:none;min-width:2.6em}
.cm-pre{flex:1;margin:0;padding:16px 18px;background:none;border:0;border-radius:0;overflow:visible;font:13px/1.65 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;color:var(--code-fg);tab-size:2;white-space:pre}
.cm-pre code{font:inherit;background:none;padding:0;color:inherit;white-space:inherit}
.cm-win.is-term .cm-pre code::selection{background:rgba(40,200,64,.25)}
.cm-win-more{display:none;width:100%;align-items:center;justify-content:center;gap:6px;border:0;border-top:1px solid var(--code-line);background:var(--code-bar);color:var(--code-muted);font:inherit;font-size:.8rem;font-weight:600;padding:9px;cursor:pointer}
.cm-win-more:hover{color:var(--code-fg)}
.cm-win-more .cm-i{width:14px;height:14px;transform:rotate(90deg)}
.cm-win[data-state="closed"] .cm-win-more,.cm-win[data-state="open"] .cm-win-more{display:none!important}
.cm-win[data-state="preview"] .cm-win-more{display:flex}
/* syntax tokens (highlight.js) */
.hljs-comment,.hljs-quote{color:var(--t-com);font-style:italic}
.hljs-keyword,.hljs-selector-tag,.hljs-doctag,.hljs-meta .hljs-keyword,.hljs-template-tag,.hljs-template-variable,.hljs-type{color:var(--t-kw)}
.hljs-string,.hljs-regexp,.hljs-meta .hljs-string,.hljs-selector-attr,.hljs-selector-pseudo{color:var(--t-str)}
.hljs-number,.hljs-literal,.hljs-symbol,.hljs-bullet,.hljs-link{color:var(--t-num)}
.hljs-title,.hljs-title.function_,.hljs-section{color:var(--t-fn)}
.hljs-attr,.hljs-attribute,.hljs-name,.hljs-selector-id,.hljs-selector-class,.hljs-property{color:var(--t-attr)}
.hljs-built_in,.hljs-variable,.hljs-params,.hljs-title.class_{color:var(--t-type)}
.hljs-meta{color:var(--code-muted)}
.hljs-addition{color:#3fb950;background:rgba(63,185,80,.14)}
.hljs-deletion{color:#f85149;background:rgba(248,81,73,.14)}
.hljs-emphasis{font-style:italic}.hljs-strong{font-weight:700}
/* ---- mermaid ---- */
.cm-mermaid{margin:0 0 1.5em;border:1px solid var(--line);border-radius:14px;background:var(--panel);overflow:hidden}
.cm-mm-bar{display:flex;align-items:center;justify-content:space-between;padding:9px 14px;border-bottom:1px solid var(--line);font-size:.78rem;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.07em}
.cm-mm-src{border:0;background:none;color:var(--accent);font:inherit;font-size:.78rem;text-transform:none;letter-spacing:0;cursor:pointer}
.cm-mm-view{padding:20px;overflow:auto;text-align:center}
.cm-mm-view svg{max-width:100%;height:auto}
.cm-mm-code{margin:0;padding:14px 16px;border-top:1px solid var(--line);background:var(--code-bg);color:var(--code-fg);font:13px/1.6 ui-monospace,Menlo,monospace;overflow:auto}
.cm-mermaid.err .cm-mm-view{color:var(--muted);font-size:.9rem}
/* ---- callouts ---- */
.cm-callout{--c:var(--accent);margin:0 0 1.5em;padding:14px 18px 14px 16px;border:1px solid color-mix(in srgb,var(--c) 35%,transparent);border-left:4px solid var(--c);border-radius:12px;background:color-mix(in srgb,var(--c) 9%,transparent);color:var(--text)}
.cm-callout>*:last-child{margin-bottom:0}
.cm-note{--c:#3b82f6}.cm-info{--c:#06b6d4}.cm-tip,.cm-success{--c:#22c55e}.cm-important{--c:#a855f7}.cm-warning{--c:#f59e0b}.cm-caution,.cm-danger,.cm-security{--c:#ef4444}
.cm-call-h{display:flex;align-items:center;gap:8px;margin-bottom:6px;color:var(--c);font-size:.88rem;text-transform:uppercase;letter-spacing:.06em}
.cm-call-h .cm-i{width:18px;height:18px}
/* ---- figures + lightbox ---- */
.cm-figure{margin:0 0 1.6em;text-align:center}
.cm-figure img{border-radius:12px;border:1px solid var(--line)}
.cm-figure figcaption,.cm-slide-cap{margin-top:10px;color:var(--muted);font-size:.88rem;line-height:1.5}
.cm-zoom{cursor:zoom-in;transition:filter .15s}
.cm-zoom:hover{filter:brightness(1.06)}
.cm-lb{position:fixed;inset:0;z-index:300;display:none;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:30px;background:rgba(6,7,10,.92)}
.cm-lb.open{display:flex}
.cm-lb img{max-width:min(1200px,94vw);max-height:80vh;object-fit:contain;border-radius:10px}
.cm-lb-cap{color:#d4d6dc;font-size:.92rem;max-width:760px;text-align:center}
.cm-lb-x,.cm-lb-n{position:absolute;display:flex;align-items:center;justify-content:center;width:44px;height:44px;border:0;border-radius:50%;background:rgba(255,255,255,.12);color:#fff;cursor:pointer}
.cm-lb-x{top:18px;right:18px}.cm-lb-prev{left:18px;top:50%}.cm-lb-next{right:18px;top:50%}
.cm-lb.single .cm-lb-n{display:none}
.cm-lb button:hover{background:rgba(255,255,255,.25)}
/* ---- slider ---- */
.cm-slider{position:relative;margin:0 0 1.6em}
.cm-slider-vp{position:relative}
.cm-track{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scroll-behavior:smooth;scrollbar-width:none;border-radius:14px;border:1px solid var(--line);background:var(--panel)}
.cm-track::-webkit-scrollbar{display:none}
.cm-slide{flex:0 0 100%;scroll-snap-align:start;padding:0;text-align:center}
.cm-slide img{width:100%;max-height:520px;object-fit:cover;border:0;border-radius:0;margin:0}
.cm-slide .cm-figure{margin:0}.cm-slide .cm-figure img{border:0;border-radius:0}
.cm-slide-cap,.cm-slide figcaption{padding:10px 16px 14px;margin:0}
.cm-sl-btn{position:absolute;top:50%;transform:translateY(-50%);width:40px;height:40px;border:0;border-radius:50%;background:rgba(0,0,0,.55);color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer;backdrop-filter:blur(4px);transition:opacity .15s,background .15s}
.cm-sl-btn:hover{background:rgba(0,0,0,.8)}
.cm-sl-btn:disabled{opacity:.25;cursor:default}
.cm-sl-prev{left:12px}.cm-sl-next{right:12px}
.cm-sl-dots{display:flex;justify-content:center;gap:7px;margin-top:12px}
.cm-sl-dot{width:8px;height:8px;padding:0;border:0;border-radius:99px;background:color-mix(in srgb,var(--text) 22%,transparent);cursor:pointer;transition:width .2s,background .2s}
.cm-sl-dot.on{width:22px;background:var(--accent)}
/* ---- tables ---- */
.cm-tablewrap{margin:0 0 1.6em;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:var(--panel)}
.cm-tablescroll{overflow-x:auto}
.cm-body .cm-tablewrap table{display:table;width:100%;margin:0;border-collapse:collapse;font-size:.95rem}
.cm-body .cm-tablewrap th,.cm-body .cm-tablewrap td{border:0;border-bottom:1px solid var(--line);padding:11px 16px;text-align:left;vertical-align:top}
.cm-body .cm-tablewrap thead th,.cm-body .cm-tablewrap tr:first-child th{background:color-mix(in srgb,var(--text) 6%,transparent);font-weight:650;font-size:.78rem;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);white-space:nowrap}
.cm-body .cm-tablewrap tbody tr:nth-child(even){background:color-mix(in srgb,var(--text) 3%,transparent)}
.cm-body .cm-tablewrap tbody tr:hover{background:color-mix(in srgb,var(--accent) 8%,transparent)}
.cm-body .cm-tablewrap tr:last-child td{border-bottom:0}
.cm-tablewrap caption{caption-side:top;padding:12px 16px;text-align:left;font-weight:650}
.cm-tablewrap th.sort{cursor:pointer}
.cm-tablewrap th.sort::after{content:"\2195";margin-left:6px;opacity:.4}
.cm-tablewrap th[data-dir="asc"]::after{content:"\2191";opacity:1;color:var(--accent)}
.cm-tablewrap th[data-dir="desc"]::after{content:"\2193";opacity:1;color:var(--accent)}
.cm-tablewrap code{white-space:nowrap}
.cm-tfilter{display:block;width:calc(100% - 24px);margin:12px;padding:9px 12px;background:var(--bg);border:1px solid var(--line);border-radius:10px;color:var(--text);font:inherit;font-size:.9rem}
.sticky-first td:first-child,.sticky-first th:first-child{position:sticky;left:0;background:var(--panel)}
/* ---- embeds, details, steps, misc ---- */
.cm-embed{position:relative;aspect-ratio:16/9;margin:0 0 1.6em;border-radius:14px;overflow:hidden;border:1px solid var(--line);background:#000}
.cm-embed iframe{position:absolute;inset:0;width:100%;height:100%;border:0}
.cm-body details{margin:0 0 1em;border:1px solid var(--line);border-radius:12px;background:var(--panel);overflow:hidden}
.cm-body summary{cursor:pointer;padding:13px 16px;font-weight:600;list-style:none;display:flex;align-items:center;justify-content:space-between;gap:12px}
.cm-body summary::-webkit-details-marker{display:none}
.cm-body summary::after{content:"+";font-size:1.3rem;line-height:1;color:var(--muted);transition:transform .2s}
.cm-body details[open] summary::after{transform:rotate(45deg)}
.cm-body details[open] summary{border-bottom:1px solid var(--line)}
.cm-body details>*:not(summary){padding:0 16px}
.cm-body details>*:not(summary):first-of-type{padding-top:14px}
.cm-body details>*:last-child{padding-bottom:14px;margin-bottom:0}
.cm-body ol.steps{list-style:none;counter-reset:s;padding:0}
.cm-body ol.steps>li{counter-increment:s;position:relative;padding:0 0 1.2em 3em;margin:0;border-left:0}
.cm-body ol.steps>li::before{content:counter(s);position:absolute;left:0;top:0;width:2em;height:2em;border-radius:50%;background:var(--accent);color:var(--on-accent);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:.85rem}
.cm-body ol.steps>li::after{content:"";position:absolute;left:1em;top:2.3em;bottom:.2em;width:1px;background:var(--line)}
.cm-body ol.steps>li:last-child::after{display:none}
.cm-body kbd{font:600 .82em ui-monospace,Menlo,monospace;padding:2px 7px;border:1px solid var(--line);border-bottom-width:2px;border-radius:6px;background:var(--panel)}
.cm-body mark{background:color-mix(in srgb,var(--accent) 25%,transparent);color:inherit;padding:0 3px;border-radius:3px}
.cm-body :not(pre)>code{font-size:.88em}
.cm-body hr{border:0;height:1px;background:var(--line);margin:2em 0}
.cm-anchor{margin-left:8px;color:var(--muted);opacity:0;vertical-align:middle;transition:opacity .15s}
.cm-anchor .cm-i{width:16px;height:16px}
h2:hover>.cm-anchor,h3:hover>.cm-anchor,h4:hover>.cm-anchor{opacity:.8}
@media (max-width:720px){
  .cm-win-meta,.cm-win-copy span{display:none}
  .cm-win-copy{padding:5px 8px}
  .cm-pre,.cm-gutter{font-size:12px}
  .cm-sl-btn{width:34px;height:34px}
  .cm-lb-prev,.cm-lb-next{top:auto;bottom:24px}
  .cm-lb-prev{left:calc(50% - 56px)}.cm-lb-next{right:calc(50% - 56px)}
}
.cm-win-more[hidden]{display:none!important}
.cm-body .cm-pre{background:none;border:0;border-radius:0;padding:16px 18px;margin:0;box-shadow:none}
.cm-body .cm-win{margin-bottom:1.5em}
.cm-body .cm-win-view{background:none}

b:if.b:template-skin:
html,body#layout{background:#f7f7f7}
body#layout{position:relative;width:auto;max-width:980px;margin:0 auto;padding:16px;font-family:Arial,sans-serif}
body#layout div.section{display:block;background:#efefef!important;border:1px solid #dcdcdc;border-radius:4px;margin:0 0 12px!important;padding:12px 14px!important}
body#layout .no-items.section{display:block}
body#layout .section h4{font-size:13px;text-transform:uppercase;color:#222;margin:0 0 8px}
body#layout .add_widget a{color:#1a73e8!important}
body#layout .widget-content{max-width:none;width:auto}
body#layout .cm-home-only,body#layout .cm-pitem,body#layout .cm-ad,body#layout .cm-sidebar,body#layout .cm-hide{display:block!important}
body#layout .cm-foot-cols{display:grid!important;grid-template-columns:repeat(3,1fr);gap:10px}
body#layout .cm-header-in,body#layout .cm-foot-bottom{display:block;height:auto;padding:0}
body#layout .cm-search,body#layout .cm-actions,body#layout .cm-logo,body#layout .cm-links{display:none!important}
body#layout .cm-wall{display:none}

