      var li = el('li'), a = el('a', '', c); a.href = '/search/label/' + encodeURIComponent(c);
      if (here.indexOf('/search/label/' + c) === 0 || c === curLabel) { a.className = 'on'; ul.parentNode.classList.add('open'); }
